def('ar_shipping','AR','Rates',0.3,T=>{const f=T.pick([5,6,7,8,10]),r=T.pick([0.5,0.75,1.25,1.5,2]),lb=T.ri(3,20);const c=r2(f+r*lb);
  return {params:[f,r,lb],prompt:`A shipping company charges ${money(f)} plus ${money2(r)} per pound. What is the cost to ship a ${lb}-pound package?`,answer:c,fmt:money2,wrong:[r2((f+r)*lb),r2(r*lb),r2(f*lb)],
   formula:'Cost = flat fee + (rate × pounds)',steps:[`${r} × ${lb} = ${money2(r*lb)}`,`${f} + ${r2(r*lb)} = ${money2(c)}`]};});
def('ar_savings','AR','Rates',0.1,T=>{const goal=T.ri(6,40)*50,save=T.pick([25,40,50,75,100]),have=T.ri(0,4)*50;const wk=(goal-have)/save;if(!Number.isInteger(wk)||wk<2)return null;
  return {params:[goal,save,have],prompt:`${T.pick(NAMES)} wants to buy a ${money(goal)} laptop and has already saved ${money(have)}. Saving ${money(save)} per week, how many more weeks will it take?`.replace(' and has already saved $0',''),answer:wk,fmt:x=>x+' weeks',wrong:[goal/save,wk+1,Math.round((goal+have)/save)],
   formula:'Weeks = (goal − already saved) ÷ weekly savings',steps:[`Still needed = ${goal} − ${have} = ${goal-have}`,`${goal-have} ÷ ${save} = ${wk} weeks`]};});
def('ar_scale_down','AR','Percents',0.8,T=>{const p=T.pick([20,25,40,50,60,75,80]),part=T.ri(2,30)*p/gcd(p,100);const whole=part*100/p;if(!Number.isInteger(whole))return null;
  return {params:[p,part],prompt:`${part} soldiers passed the swim test, which is ${p}% of the platoon. How many soldiers are in the platoon?`,answer:whole,wrong:[part*p/100,part+p,whole-part],
   formula:'Whole = Part ÷ Percent (as a decimal)',steps:[`${p}% = ${p/100}`,`Whole = ${part} ÷ ${p/100} = ${whole}`]};});
def('ar_paint','AR','Area (word problem)',0.9,T=>{const l=T.ri(10,20),h=T.pick([8,9,10]);const cov=T.pick([300,350,400]);const walls=2*(l+l)*h;const cans=Math.ceil(walls/cov);if(walls%cov===0)return null;
  return {params:[l,h,cov],prompt:`The four walls of a square room are each ${l} feet wide and ${h} feet high. One can of paint covers ${cov} square feet. How many cans must be bought to give the walls one coat?`,answer:cans,fmt:x=>x+(x===1?' can':' cans'),wrong:[Math.floor(walls/cov),Math.ceil(l*l/cov)||1,cans+2],
   formula:'Wall area = perimeter × height; round UP to whole cans',steps:[`Wall area = 4 × ${l} × ${h} = ${walls} sq ft`,`${walls} ÷ ${cov} ≈ ${r2(walls/cov)}`,`Round up: ${cans} cans`]};});

