def('mk_recip_abs','MK','Number properties',-0.6,T=>{const t=T.pick(['recip','abs']);if(t==='recip'){const n=T.ri(2,9),d=T.ri(2,9);if(n===d||gcd(n,d)>1)return null;return {params:[t,n,d],prompt:`What is the reciprocal of ${n}/${d}?`,answer:d+'/'+n,wrong:['−'+n+'/'+d,'−'+d+'/'+n,'1'],formula:'The reciprocal of a/b is b/a (their product is 1)',steps:[`${n}/${d} × ${d}/${n} = 1, so the reciprocal is ${d}/${n}`]};}
  const a=T.ri(-15,-2),b=T.ri(3,12);const v=Math.abs(a)-Math.abs(b-2*b);return {params:[t,a,b],prompt:`What is the value of |${neg(a)}| − |${neg(-b)}|?`,answer:-a-b,fmt:neg,nonneg:false,wrong:[a-b,-a+b,a+b],formula:'Absolute value is the distance from 0 (never negative)',steps:[`|${neg(a)}| = ${-a}, |${neg(-b)}| = ${b}`,`${-a} − ${b} = ${neg(-a-b)}`]};});
def('mk_proportion','MK','Ratios and proportions',-0.1,T=>{const a=T.ri(2,9),b=T.ri(2,12),k=T.ri(2,7);if(a===b)return null;
  return {params:[a,b,k],prompt:`Solve for x: ${a}/${b} = x/${b*k}`,answer:a*k,wrong:[b*k/a,a+b*k-b,a*b],formula:'Cross-multiply: a/b = x/c → x = ac/b',steps:[`${b}x = ${a} × ${b*k} = ${a*b*k}`,`x = ${a*b*k} ÷ ${b} = ${a*k}`]};});
def('mk_stats','MK','Statistics',0,T=>{const n=T.pick([5,7]);const xs=[];for(let i=0;i<n;i++)xs.push(T.ri(2,30));const s=[...xs].sort((a,b)=>a-b);const ask=T.pick(['median','range','mode']);
  if(ask==='mode'){xs[n-1]=xs[1];}const so=[...xs].sort((a,b)=>a-b);const cnt={};xs.forEach(v=>cnt[v]=(cnt[v]||0)+1);const mx=Math.max(...Object.values(cnt));const modes=Object.keys(cnt).filter(k=>cnt[k]===mx);if(ask==='mode'&&modes.length!==1)return null;
  const ans=ask==='median'?so[(n-1)/2]:ask==='range'?so[n-1]-so[0]:+modes[0];const mean=xs.reduce((a,b)=>a+b,0)/n;
  return {params:[xs,ask],prompt:`What is the ${ask} of this set of numbers: ${xs.join(', ')}?`,answer:ans,wrong:[xs[(n-1)/2],Number.isInteger(mean)?mean:Math.round(mean),so[n-1],so[0]+so[n-1]],
   formula:ask==='median'?'Median = middle value after sorting':ask==='range'?'Range = largest − smallest':'Mode = most frequent value',steps:[`Sorted: ${so.join(', ')}`,ask==='median'?`Middle value = ${ans}`:ask==='range'?`${so[n-1]} − ${so[0]} = ${ans}`:`${ans} appears most often`]};});
def('mk_slope','MK','Coordinate geometry',0.4,T=>{const x1=T.ri(-6,6),y1=T.ri(-6,6);const dx=T.ri(1,6)*(T.r()<0.3?-1:1),dy=T.ri(-8,8);if(!dy)return null;const x2=x1+dx,y2=y1+dy;
  return {params:[x1,y1,x2,y2],prompt:`What is the slope of the line that passes through (${neg(x1)}, ${neg(y1)}) and (${neg(x2)}, ${neg(y2)})?`,answer:frac(dy,dx).replace(/^-/,'−'),wrong:[frac(dx,dy).replace(/^-/,'−'),frac(-dy,dx).replace(/^-/,'−'),frac(y2+y1,x2+x1||1).replace(/^-/,'−')],
   formula:'m = (y₂ − y₁) ÷ (x₂ − x₁)',steps:[`m = (${neg(y2)} − ${y1<0?'('+neg(y1)+')':y1}) ÷ (${neg(x2)} − ${x1<0?'('+neg(x1)+')':x1}) = ${neg(dy)}/${neg(dx)} = ${frac(dy,dx).replace(/^-/,'−')}`]};});
def('mk_line_eq','MK','Coordinate geometry',0.8,T=>{const m=T.ri(-4,4),b=T.ri(-6,6);if(!m)return null;const x1=0,x2=T.ri(1,3);const y1=b,y2=m*x2+b;const L=(mm,bb)=>`y = ${mm===1?'':mm===-1?'−':neg(mm)}x${bb?sgn(bb):''}`;
  return {params:[m,b,x2],prompt:`What is the equation of the line that passes through the points (0, ${neg(y1)}) and (${x2}, ${neg(y2)})?`,answer:L(m,b),wrong:[L(-m,b),L(m,-b||1),L(b||1,m)],
   formula:'y = mx + b, where m = slope and b = y-intercept',steps:[`m = (${neg(y2)} − ${y1<0?'('+neg(y1)+')':y1}) ÷ (${x2} − 0) = ${neg(m)}`,`The line crosses the y-axis at (0, ${neg(b)}), so b = ${neg(b)}`,L(m,b)]};});
def('mk_system','MK','Systems of equations',1.0,T=>{const x=T.ri(-5,8),y=T.ri(-5,8);const a=T.ri(1,3),b=T.ri(1,3);const s1=x+y,s2=a*x-b*y;if(a===0)return null;
  return {params:[x,y,a,b],prompt:`If x + y = ${neg(s1)} and ${a===1?'':a}x − ${b===1?'':b}y = ${neg(s2)}, what is the value of x?`,answer:x,fmt:neg,nonneg:false,wrong:[y,s1-x+1===x?x+3:s1,-x],
   formula:'Substitute y = (sum) − x into the second equation',steps:[`y = ${neg(s1)} − x`,`${a===1?'':a}x − ${b===1?'':b}(${neg(s1)} − x) = ${neg(s2)}  →  ${a+b}x = ${neg(s2+b*s1)}`,`x = ${neg(x)} (and y = ${neg(y)})`]};});
def('mk_angles','MK','Angles',-0.4,T=>{const t=T.pick(['supp','comp','tri','vert']);const a=T.ri(15,75);let ans,pr,f;
  if(t==='supp'){const b=T.ri(25,155);ans=180-b;pr=`What is the measure of the supplement of a ${b}° angle?`;f='Supplementary angles add up to 180°';}
  else if(t==='comp'){ans=90-a;pr=`What is the measure of the complement of a ${a}° angle?`;f='Complementary angles add up to 90°';}
  else if(t==='tri'){const b=T.ri(25,80),c=T.ri(25,80);ans=180-b-c;pr=`Two angles of a triangle measure ${b}° and ${c}°. What is the measure of the third angle?`;f='The angles of a triangle add up to 180°';}
  else{const b=T.ri(25,155);ans=180-b;pr=`Two lines intersect. One of the angles formed measures ${b}°. What is the measure of an angle adjacent to it?`;f='Adjacent angles formed by intersecting lines are supplementary (add to 180°)';}
  return {params:[t,pr],prompt:pr,answer:ans,fmt:x=>x+'°',wrong:[ans+10,Math.abs(90-ans)||45,360-ans,180-ans],formula:f,steps:[`${f}: ${ans}°`]};});
def('mk_polygon','MK','Polygons',0.6,T=>{const n=T.pick([5,6,8,10,12]);const name={5:'pentagon',6:'hexagon',8:'octagon',10:'decagon',12:'dodecagon'}[n];const s=(n-2)*180;const ask=T.r()<0.5;
  return {params:[n,ask],prompt:ask?`What is the sum of the interior angles of a ${name}?`:`What is the measure of each interior angle of a regular ${name}?`,answer:ask?s:s/n,fmt:x=>r2(x)+'°',wrong:ask?[n*180,360,(n-1)*180]:[360/n,s,180-s/n+180/n*0],
   formula:'Sum of interior angles = (n − 2) × 180°',steps:[`n = ${n}: (${n} − 2) × 180° = ${s}°`].concat(ask?[]:[`Each angle = ${s}° ÷ ${n} = ${r2(s/n)}°`])};});
def('mk_pyth','MK','Pythagorean theorem',0.2,T=>{const t=T.pick([[3,4,5],[5,12,13],[8,15,17],[7,24,25],[20,21,29]]);const k=T.pick([1,2,3]);const [a,b,c]=t.map(v=>v*k);if(c>60)return null;const miss=T.pick(['c','b']);
  return {params:[a,b,miss],prompt:miss==='c'?`A right triangle has legs of ${a} and ${b}. What is the length of the hypotenuse?`:`A right triangle has a hypotenuse of ${c} and one leg of ${a}. What is the length of the other leg?`,
   answer:miss==='c'?c:b,wrong:miss==='c'?[a+b,Math.round((a*a+b*b)/2),c+2]:[c-a,c+a,b+1],formula:'a² + b² = c²',steps:miss==='c'?[`c² = ${a}² + ${b}² = ${a*a} + ${b*b} = ${c*c}`,`c = √${c*c} = ${c}`]:[`b² = ${c}² − ${a}² = ${c*c} − ${a*a} = ${b*b}`,`b = √${b*b} = ${b}`]};});
def('mk_circle','MK','Circles',0,T=>{const r=T.ri(2,12);const t=T.pick(['area','circ','diam']);const dsc=t==='diam'?`a diameter of ${2*r}`:`a radius of ${r}`;const what=t==='circ'?'circumference':'area';
  const ans=what==='area'?`${r*r}π`:`${2*r}π`;return {params:[r,t],prompt:`A circle has ${dsc}. What is its ${what}?`,answer:ans,wrong:what==='area'?[`${2*r}π`,`${4*r*r}π`,`${r}π`]:[`${r*r}π`,`${r}π`,`${4*r}π`],
   formula:'Area = πr²;  Circumference = 2πr;  radius = diameter ÷ 2',steps:(t==='diam'?[`r = ${2*r} ÷ 2 = ${r}`]:[]).concat([what==='area'?`A = π × ${r}² = ${r*r}π`:`C = 2 × π × ${r} = ${2*r}π`])};});
def('mk_rect','MK','Area / perimeter',-0.5,T=>{const l=T.ri(4,20),w=T.ri(2,15);if(l===w)return null;const t=T.pick(['area','per','findw']);
  if(t==='findw'){const A=l*w;return {params:[l,w,t],prompt:`A rectangle has an area of ${A} square inches and a length of ${l} inches. What is its width?`,answer:w,fmt:x=>x+' inches',wrong:[A-l,A/2-l>0?A/2-l:w+3,l],formula:'A = l × w  →  w = A ÷ l',steps:[`w = ${A} ÷ ${l} = ${w} inches`]};}
  return {params:[l,w,t],prompt:`What is the ${t==='area'?'area':'perimeter'} of a rectangle ${l} feet long and ${w} feet wide?`,answer:t==='area'?l*w:2*(l+w),fmt:x=>x+(t==='area'?' square feet':' feet'),wrong:t==='area'?[2*(l+w),l+w,l*w*2]:[l*w,l+w,2*l+w],
   formula:t==='area'?'A = l × w':'P = 2l + 2w',steps:[t==='area'?`${l} × ${w} = ${l*w} sq ft`:`2(${l}) + 2(${w}) = ${2*(l+w)} ft`]};});
def('mk_triangle_area','MK','Area / perimeter',0,T=>{const b=T.ri(3,20),h=T.ri(2,16);if((b*h)%2)return null;
  return {params:[b,h],prompt:`A triangle has a base of ${b} centimeters and a height of ${h} centimeters. What is its area?`,answer:b*h/2,fmt:x=>x+' cm²',wrong:[b*h,b+h,b*h/2+b],formula:'A = ½ × base × height',steps:[`A = ½ × ${b} × ${h} = ${b*h/2} cm²`]};});
def('mk_volume','MK','Volume',0.5,T=>{const t=T.pick(['box','cyl','cube']);if(t==='cyl'){const r=T.ri(1,6),h=T.ri(2,10);return {params:[t,r,h],prompt:`What is the volume of a cylinder with a radius of ${r} and a height of ${h}?`,answer:`${r*r*h}π`,wrong:[`${2*r*h}π`,`${r*h}π`,`${4*r*r*h}π`],formula:'V = πr²h',steps:[`V = π × ${r}² × ${h} = ${r*r*h}π`]};}
  if(t==='cube'){const s=T.ri(2,9);return {params:[t,s],prompt:`What is the volume of a cube with edges ${s} inches long?`,answer:s**3,fmt:x=>x+' cubic inches',wrong:[s*s,6*s*s,3*s],formula:'V = s³',steps:[`${s} × ${s} × ${s} = ${s**3}`]};}
  const l=T.ri(2,12),w=T.ri(2,9),h=T.ri(2,8);return {params:[t,l,w,h],prompt:`What is the volume of a rectangular box ${l} inches long, ${w} inches wide, and ${h} inches high?`,answer:l*w*h,fmt:x=>x+' cubic inches',wrong:[l+w+h,2*(l*w+w*h+l*h),l*w],formula:'V = l × w × h',steps:[`${l} × ${w} × ${h} = ${l*w*h}`]};});
def('mk_square_diag','MK','Pythagorean theorem',1.0,T=>{const s=T.ri(2,12);
  return {params:[s],prompt:`What is the length of the diagonal of a square with sides of ${s}?`,answer:`${s}√2`,wrong:[`${2*s}`,`${s*s}`,`2√${s}`],formula:'Diagonal of a square = side × √2 (from a² + a² = d²)',steps:[`d² = ${s}² + ${s}² = ${2*s*s}`,`d = √${2*s*s} = ${s}√2`]};});
def('mk_word_eq','MK','Linear equations',0.3,T=>{const k=T.ri(2,6),b=T.ri(1,15),x=T.ri(2,20);const v=k*x+b;
  return {params:[k,b,x],prompt:`${b} more than ${k} times a number is ${v}. What is the number?`,answer:x,wrong:[(v+b)/k,v-b,x+b],formula:'Translate: "b more than k times n" → kn + b',steps:[`${k}n + ${b} = ${v}`,`${k}n = ${v-b}`,`n = ${x}`]};});
def('mk_factorial_perm','MK','Counting',0.8,T=>{const n=T.ri(4,7);const t=T.pick(['fact','arr']);
  const f=k=>k<=1?1:k*f(k-1);if(t==='fact')return {params:[t,n],prompt:`What is the value of ${n}! ÷ ${n-2}!?`,answer:n*(n-1),wrong:[n,f(n),2],formula:'n! = n × (n − 1) × … × 1',steps:[`${n}!/${n-2}! = ${n} × ${n-1} = ${n*(n-1)}`]};
  return {params:[t,n],prompt:`In how many different orders can ${n} soldiers stand in a line?`,answer:f(n),wrong:[n*n,n*(n-1),2*n],formula:'Arrangements of n different items = n!',steps:[`${Array.from({length:n},(_,i)=>n-i).join(' × ')} = ${f(n)}`]};});

