function plan(){
  const p=state.plan;
  if(!p){const d=E.diagAnswered(state);app.innerHTML=`<div class="card"><h2>Study plan</h2><p>Your personalized plan is generated when the 40-question diagnostic is finished. Progress: ${d}/40.</p><a class="btn gold" href="#quiz" onclick="resumeDiag()">Continue diagnostic (Q${d+1})</a></div>${DISC}`;return;}
  app.innerHTML=`<div class="card"><h2>Diagnostic results</h2><p>${esc(p.summary)}</p><table><tr><th>Subject</th><th>Score</th><th>%</th></tr>${p.core.map(c=>`<tr><td>${c.name}</td><td>${c.correct}/${c.total}</td><td>${c.pct}%</td></tr>`).join('')}</table>
   ${p.topics.length?`<p><b>Weakest topics:</b> ${p.topics.map(t=>esc(t.topic)+' ('+t.pct+'%)').join(', ')}</p>`:''}
   <button class="btn alt" onclick="state.plan=E.buildPlan(state);save();plan()">Refresh plan with latest results</button></div>
   <div class="card"><h2>14-day plan</h2><table>${p.days.map(d=>`<tr><td><b>Day ${d.day}</b></td><td>${d.tasks.map(esc).join('<br>')}</td></tr>`).join('')}</table>
   <p class="muted">Tip: GT = VE (WK+PC) + AR. Many OCS packets require GT ≥ 110; confirm the current requirement with your recruiter.</p></div>${DISC}`;
}
function history(){
  const H=state.history.slice().reverse();const f=(location.hash.split('/')[1]||'all');
  const list=H.filter(h=>f==='all'||(f==='missed'&&!h.correct)||(f==='diag'&&h.mode==='diagnostic'));
  app.innerHTML=`<div class="card"><h2>Answer history (${state.history.length} answers)</h2>
   <a class="btn ${f==='all'?'':'alt'}" href="#history/all">All</a><a class="btn ${f==='diag'?'':'alt'}" href="#history/diag">Diagnostic</a><a class="btn ${f==='missed'?'':'alt'}" href="#history/missed">Missed</a>
   ${list.map(h=>`<details style="border-bottom:1px solid var(--line);padding:6px 0"><summary><b class="${h.correct?'ok':'no'}">${h.correct?'✔':'✘'}</b> ${h.mode==='diagnostic'?'Diag Q'+h.n:esc(h.mode)+' Q'+h.n} · ${S[h.subject]} · <span class="muted">${esc(h.topic)} · ${new Date(h.ts).toLocaleString()}</span></summary>
   <div style="padding:8px 0 4px 18px">${h.passage?`<div class="passage">${esc(h.passage)}</div>`:''}<div>${safe(h.prompt)}</div>
   ${h.imported?(h.correctLabel?`<p>Correct answer: ${esc(h.correctLabel)}</p>`:''):h.choices.map((c,i)=>`<div class="${i===h.answer?'ok':i===h.chosen?'no':''}">${'ABCD'[i]}. ${esc(c)} ${i===h.answer?'✔ correct':''}${i===h.chosen&&i!==h.answer?' ✘ your answer':''}</div>`).join('')+`<div class="fb ${h.correct?'ok':'no'}">${h.formula?'Formula: '+esc(h.formula)+'\n':''}${esc(h.explanation)}</div>`}</div></details>`).join('')}</div>`;
}
function data(){
  const rp=state.reported||[],vd=state.voided||[];
  app.innerHTML=bookPackCard()+recentCard()+`<div class="card" id="repCard"><h2>Reported questions</h2><p class="muted">${rp.length} question(s) excluded from future draws · ${vd.length} answer(s) voided (not counted in any score).</p>${rp.map(r=>`<p class="small">${esc(r.subject||'')} · ${esc(String(r.prompt||'').slice(0,90))}${r.source?' — '+esc(srcText(r.source)):''}${r.answered?' <b>(answer voided)</b>':' (skipped before answering)'}</p>`).join('')}</div>`+`<div class="card"><h2>Training pace (virtual deadline)</h2><p class="muted">No test date yet? The app paces you toward a self-set target so you build steadily instead of cramming. Change it anytime; when it passes, the app switches to maintenance mode.</p>
  Start: <b>${E.ensurePace(state).startDate}</b> &nbsp; Target: <input type="date" id="tdate" value="${state.pace.targetDate}"> Minutes/day: <input type="number" id="tmin" min="10" max="120" value="${state.pace.dailyMinutes}" style="width:70px"> Days/week: <input type="number" id="tdays" min="3" max="7" value="${state.pace.daysPerWeek}" style="width:60px">
  <button class="btn" onclick="savePace()">Save</button></div>
  <div class="card"><h2>Save & backup</h2>
  <p><b>Storage mode: ${MODE==='desktop'?'Desktop app file — saved after every answer':MODE==='server'?'Server file':window.STORAGE_OK===false?'<span class="bad">NOT SAVED — this viewer blocks storage. Export (copy the text) before closing.</span>':'This iPhone app only (on-device storage)'}</b></p>
  <p class="muted">${MODE==='server'?'Every answer is saved immediately to a JSON file on the app server (plus hourly backup copies), so progress survives closing the browser and switching devices that use the same link. Limitations: there are no user accounts or passwords — anyone with the link can see and change this progress; if the server or tunnel is down you cannot load the app from that link, and if the server machine is reset the file could be lost. Export a backup regularly.':'Progress is saved on this phone after every answer, separately from the PC app (no syncing). Deleting the Home Screen app or clearing Safari website data erases it. Use Export regularly (save the file to Files) and Import to restore it, or to bring over progress exported from the PC app.'}</p>
  ${MODE==='desktop'?(()=>{const i=ASVAB_NATIVE.info();return `<p class="small" id="deskFile">File: <code>${esc(i.file)}</code> · ${i.backups} rolling backup(s), keeps last ${i.keep} <button class="btn alt" onclick="ASVAB_NATIVE.showDataFolder()">Open data folder</button></p>`;})():''}
  <button class="btn" id="bExport" onclick="exportJSON()">Export progress (JSON)</button><button class="btn alt" id="bSaveAs" onclick="saveAsJSON()">Save as… (file picker)</button><button class="btn alt" id="bShowExport" onclick="showExport()">Show export text</button>
  ${MODE==='desktop'?'<button class="btn alt" id="bOpenImport" onclick="nativeOpenImport()">Import progress (open file…)</button>':''}<label class="btn alt"${MODE==='desktop'?' style="display:none"':''}>Import progress<input type="file" accept=".json,application/json" style="display:none" onchange="importJSON(this.files[0])"></label>
  <div id="exportBox"></div>
  <h3>Import by pasting text</h3><p class="muted">If file import/export is blocked (e.g. a file preview window), paste previously exported JSON here.</p><textarea id="pasteIn" rows="6" style="width:100%" placeholder="Paste exported JSON here"></textarea><button class="btn" id="bPasteImport" onclick="importText($('#pasteIn').value)">Import pasted text</button>
  <p class="muted">Import replaces current progress after validation (duplicate answers or diagnostic numbering gaps are rejected).</p></div>
  <div class="card" id="aboutQ"><h2>About the questions</h2><p class="muted">Math, mechanical and electrical problems are also generated by code that computes the answer from the numbers shown (unlimited variety). Book questions come from your two ASVAB For Dummies PDFs (personal study use only), audited by the integrity checker; original items are hand-written. Answered and reported questions are avoided.</p>${poolTable()}</div>
  <div class="card"><h2>Reset</h2><button class="btn alt" onclick="resetAll()">Reset to imported history (Q1–25)</button></div>${DISC}`;
}
function savePace(){const e=E.setTarget(state,$('#tdate').value);if(e)return note(e);if(window.ASVABMERGE)ASVABMERGE.touch(state,'pace');state.pace.dailyMinutes=Math.max(10,+$('#tmin').value||30);state.pace.daysPerWeek=Math.min(7,Math.max(3,+$('#tdays').value||6));save();note('Pace saved.');}
async function nativeOpenImport(){try{const f=await ASVAB_NATIVE.openFile();if(!f)return;await importText(f.text);if(state.history&&!state.desktopWelcomed){state.desktopWelcomed=true;save();}}catch(e){note('Could not open file: '+e.message);}}
function welcomeCard(){if(MODE!=='desktop'||state.desktopWelcomed)return '';return `<div class="card" id="welcomeCard"><h2>Welcome to the desktop app</h2><p>Your progress is now saved to a file on this PC after every answer. Have progress from the browser/preview version? Bring it over once:</p>
  <button class="btn gold" id="bWelcomeOpen" onclick="nativeOpenImport()">Open exported .json file…</button> <a class="btn alt" href="#data" onclick="setTimeout(()=>{const t=$('#pasteIn');if(t){t.scrollIntoView();t.focus();}},100)">Paste exported text</a> <button class="btn alt" id="bWelcomeSkip" onclick="state.desktopWelcomed=true;save();nav()">Start fresh / dismiss</button></div>`;}
function exportText(){return JSON.stringify(state,null,1);}
function exportName(){return 'asvab-progress-'+new Date().toISOString().slice(0,10)+'.json';}
// Export: try a normal download, then always offer the copyable text (download may be silently blocked in previews/sandboxes).
function exportJSON(){if(MODE==='desktop'){ASVAB_NATIVE.exportFile(exportText(),exportName()).then(r=>{if(r&&r.ok)note('Exported to '+r.path);else if(!(r&&r.canceled))showExport('Export failed — copy the text below instead.');});return;}let tried=false;try{const b=new Blob([exportText()],{type:'application/json'});const u=URL.createObjectURL(b);const a=document.createElement('a');a.href=u;a.download=exportName();a.rel='noopener';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),4000);tried=true;}catch(e){}
  showExport(tried?'A download was started. If no file appeared (some previews block downloads), copy the text below and save it as a .json file.':'Downloads are not available here. Copy the text below and save it as a .json file.');}
async function saveAsJSON(){if(MODE==='desktop')return exportJSON();if(!window.showSaveFilePicker){showExport('This viewer has no file-save dialog. Copy the text below instead.');return;}
  try{const h=await window.showSaveFilePicker({suggestedName:exportName(),types:[{description:'JSON',accept:{'application/json':['.json']}}]});const w=await h.createWritable();await w.write(exportText());await w.close();note('Saved '+h.name);}
  catch(e){if(e&&e.name==='AbortError')return;showExport('Saving was blocked here ('+(e&&e.name||'error')+'). Copy the text below instead.');}}
function showExport(msg){const box=$('#exportBox');if(!box)return;box.innerHTML=`<div class="card inner"><p class="muted">${esc(msg||'Your full progress as JSON. Copy it and keep it somewhere safe; import it later with “Import by pasting text”.')}</p>
  <textarea id="exportText" rows="12" style="width:100%" readonly></textarea><button class="btn gold" id="bCopy" onclick="copyExport()">Copy to clipboard</button> <button class="btn alt" onclick="selectExport()">Select all</button> <span id="copyMsg" class="muted"></span></div>`;$('#exportText').value=exportText();box.scrollIntoView({block:'nearest'});}
function selectExport(){const t=$('#exportText');t.focus();t.select();try{t.setSelectionRange(0,t.value.length);}catch(e){}}
async function copyExport(){const t=$('#exportText');const m=$('#copyMsg');let ok=false;
  try{if(navigator.clipboard&&window.isSecureContext!==false){await navigator.clipboard.writeText(t.value);ok=true;}}catch(e){}
  if(!ok){try{selectExport();ok=document.execCommand('copy');}catch(e){ok=false;}}
  if(!ok)selectExport();m.textContent=ok?'Copied ✓ — paste it into a text file and save as .json':'Clipboard blocked here: the text is selected — press Ctrl+C (Cmd+C on Mac).';m.dataset.ok=ok?'1':'0';}
async function importText(txt){try{if(!String(txt||'').trim())return note('Paste exported JSON first.');const s=JSON.parse(txt);const err=E.validate(s);if(err)return note('Import rejected: '+err);
  E.repair(s);if(!await ask(`Import ${s.history.length} answers? This replaces current progress (${state.history.length} answers).`))return;if(MODE==='desktop')s.desktopWelcomed=true;state=s;lastFeedback=null;await save(true);note('Imported.');nav();}catch(e){note('Invalid JSON: '+e.message);}}
function importJSON(f){if(!f)return;const r=new FileReader();r.onload=async()=>{try{const s=JSON.parse(r.result);const err=E.validate(s);if(err)return note('Import rejected: '+err);
  E.repair(s);if(!await ask(`Import ${s.history.length} answers? This replaces current progress (${state.history.length} answers).`))return;if(MODE==='desktop')s.desktopWelcomed=true;state=s;lastFeedback=null;await save(true);note('Imported.');nav();}catch(e){note('Invalid file: '+e.message);}};r.readAsText(f);}
async function resetAll(){if(!await ask('Erase all progress except the imported Q1–25? Export first if unsure.'))return;state=E.newState();lastFeedback=null;await save(true);nav();}
load().then(()=>{if(state)E.repair(state);if(!window.PWA&&!(window.BOOK_BANK&&window.BOOK_BANK.length))setTimeout(()=>note('⚠ Book question bank did not load — check the Practice page counts.'),500);window.STORAGE_OK=true;let stOK=true;try{localStorage.setItem('asvab-probe','1');localStorage.removeItem('asvab-probe');}catch(e){stOK=false;window.STORAGE_OK=false;}if(window.STANDALONE&&!stOK){setTimeout(()=>banner('⚠ This viewer blocks browser storage — progress will be lost when it closes. Use Data → Export (copy the text) before closing.'),0);}if(window.PWA&&!(window.BOOK_BANK&&window.BOOK_BANK.length))banner('Book questions aren’t on this phone yet — <a href="#data">Data → Import book questions</a>. Original and generated questions work now.');else if(MODE==='local'&&!window.PWA)banner(window.STANDALONE?'Standalone mode: progress is saved in this browser only. Use Data → Export to back it up.':'Server unavailable — saving to this browser only. Use Data → Export to back up.');nav();phoneAfterLoad();});
